#include "MatrixMiniR4.h"

float last;
float on;

void setup()
{
  MiniR4.begin();
  MiniR4.PWR.setBattCell(2);
  Serial.begin(9600);
  last = 0;
  on = 0;
}

void loop()
{
  if((millis() - last) > 500)
  {
    last = millis();
    on = 1 - on;
  }
  if(on == 1)
  {
    MiniR4.LED.setColor(1, 0, 0, 255);
  }
  else
  {
    MiniR4.LED.setColor(1, 0, 0, 0);
  }
  if(MiniR4.BTN_UP.getState())
  {
    MiniR4.LED.setColor(2, 255, 0, 0);
  }
  else
  {
    MiniR4.LED.setColor(2, 0, 0, 0);
  }

}

